package com.gamehub;
import com.gamehub.application.*; import com.gamehub.infrastructure.*; import org.junit.jupiter.api.Test; import java.nio.file.*; import java.time.*; import static org.junit.jupiter.api.Assertions.*;
class SessionSliceTest { @Test void sessionRequiresConfirmedReservationAndRejectsDuplicateActive() throws Exception {Path p=Files.createTempFile("session-", ".db");try(Database db=new Database(p)){var us=new UserService(db);us.bootstrap("m","password1");var u=us.authenticate("m","password1");var o=new OperationsService(db);long station=o.addStation("S-01","PC",50000);long reservation=o.reserve(u.id(),station,Instant.now().plusSeconds(3600),Instant.now().plusSeconds(7200));long session=o.startSession(reservation);assertTrue(session>0);assertThrows(IllegalStateException.class,()->o.startSession(reservation));assertEquals(session,o.finishSession(session,5000));}finally{Files.deleteIfExists(p);}}}
